// Package show holds the light shows built into the firmware: the original iCubeSmart cartoons
// as Go functions (generated by tools/showgen: Dynamic in dynamic.go, Audio in audio.go, Test in
// test.go, shapes, palettes and Keys in library.go).
package show

import "github.com/Tariomka/stm32-led-cube/internal/engine/keyframe"

var library = &keyframe.Library{Shapes: shapes, Palettes: palettes}

// New makes a playable show of cartoons with the original key functions.
func New(cartoons []func() *keyframe.Cartoon) *keyframe.Show {
	return &keyframe.Show{Cartoons: cartoons, Keys: Keys}
}

// SetMissing reports unknown shape or palette names (diagnostics).
func SetMissing(report func(kind, name string)) {
	library.Missing = report
}
